/**
 * Unit tests for PiePlot.getExplodePercent(Comparable key)
 */
public class PiePlot_getExplodePercent_TriageGen2Test {

    private PiePlot piePlot;

    @Before
    public void setUp() {
        piePlot = new PiePlot();
    }

    /**
     * Tests that the method returns 0.0 when explodePercentages map is null.
     * Covers: if (this.explodePercentages != null) -> false
     */
    @Test
    public void testGetExplodePercent_NullMap() {
        // By default, explodePercentages is null in a new PiePlot instance
        double result = piePlot.getExplodePercent("Key");
        assertEquals(0.0, result, 0.0001);
    }

    /**
     * Tests that the method returns 0.0 when the key is not present in the map.
     * Covers: if (percent != null) -> false
     */
    @Test
    public void testGetExplodePercent_KeyNotFound() {
        piePlot.setExplodePercent("ExistingKey", 0.15);

        // Requesting a key that wasn't set
        double result = piePlot.getExplodePercent("NonExistentKey");
        assertEquals(0.0, result, 0.0001);
    }

    /**
     * Tests that the method returns the correct double value when the key exists.
     * Covers: if (this.explodePercentages != null) -> true AND if (percent != null) -> true
     */
    @Test
    public void testGetExplodePercent_Success() {
        String key = "CategoryA";
        double expectedPercent = 0.25;

        piePlot.setExplodePercent(key, expectedPercent);
        double result = piePlot.getExplodePercent(key);

        assertEquals(expectedPercent, result, 0.0001);
    }

    /**
     * Tests that the method handles different types of Number implementations (Integer/Double).
     * This ensures the (Number) cast and doubleValue() call work correctly.
     */
    @Test
    public void testGetExplodePercent_DifferentNumberTypes() {
        // Testing with an integer-based value implicitly via setExplodePercent logic
        // although setExplodePercent takes double, the underlying map stores it as a Number.
        piePlot.setExplodePercent("IntKey", 1.0);
        assertEquals(1.0, piePlot.getExplodePercent("IntKey"), 0.0001);

        piePlot.setExplodePercent("DoubleKey", 0.12345);
        assertEquals(0.12345, piePlot.getExplodePercent("DoubleKey"), 0.0001);
    }
}
